nms = {
    "nm1": {"mem": 8, "cores": 8, "used_mem": 0, "used_cores": 0},
    "nm2": {"mem": 8, "cores": 8, "used_mem": 0, "used_cores": 0},
}
req = {"mem": 2, "cores": 1, "n": 3}
allocated = []
for _ in range(req["n"]):
    for nm, r in nms.items():
        if r["used_mem"] + req["mem"] <= r["mem"] and r["used_cores"] + req["cores"] <= r["cores"]:
            r["used_mem"] += req["mem"]
            r["used_cores"] += req["cores"]
            allocated.append(nm)
            break
print("allocated containers on:", allocated)
for nm, r in nms.items():
    print(f"{nm}: mem {r['used_mem']}/{r['mem']} cores {r['used_cores']}/{r['cores']}")
